import 'package:flutter/material.dart';import 'package:myapper_bloc/flutter_bloc.dart';import 'package:myapp/pages/authentication/login_page.dart';import 'package:myapp/utils/app_theme.dart';import 'package:myapp/cubits/auth_cubit.dart';class LogoutDialog {  static void show(BuildContext context) {    showDialog(      context: context,      barrierDismissible: false,      builder: (BuildContext context) {        final colors = Theme.of(context).extension<AppColorsExtension>()!;        return AlertDialog(          backgroundColor: colors.cardColor,          title: Text('Logout', style: TextStyle(color: colors.textColor)),          content: Text('Are you sure you want to logout?',              style: TextStyle(color: colors.textColor)),          actions: [            TextButton(                onPressed: () => Navigator.pop(context),                child: const Text('Cancel')),            TextButton(              onPressed: () async {                await context.read<AuthCubit>().logout();                if (context.mounted) {                  Navigator.pushAndRemoveUntil(                    context,                    MaterialPageRoute(builder: (context) => const LoginPage()),                    (route) => false,                  );                }              },              child: const Text('Logout', style: TextStyle(color: Colors.red)),            ),          ],        );      },    );  }}